(()=>{
'use strict';
const $=s=>document.querySelector(s),form=$('#editor');let items=[],selected=null,csrf='',dirty=false;
const numberFields=['price','power','range','weight','load'];
const stockLabels={in_stock:'В наличии',out_of_stock:'Нет в наличии',on_order:'Под заказ',unknown:'Наличие уточняется'};
const errors={conflict:'Товар изменён в другом окне. Обновите страницу перед сохранением.',invalid_credentials:'Неверный логин или пароль.',rate_limit:'Слишком много попыток. Повторите через 15 минут.',not_configured:'Серверная админка ещё не подключена к хостингу.',type_required:'Выберите раздел для публикации товара.'};
async function api(action,data){const response=await fetch('../api/admin.php?action='+action,{method:data?'POST':'GET',cache:'no-store',headers:data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:data?JSON.stringify(data):undefined});let j;try{j=await response.json();}catch{throw Error('not_configured');}if(!response.ok){if(response.status===401&&action!=='login'){showLogin();throw Error('session_expired');}throw Error(j.error||'server_error');}return j;}
function say(el,text,error=false){el.textContent=text;el.dataset.error=String(error);}
function errorText(e){return errors[e.message]||(e.message==='session_expired'?'Войдите снова.':'Не удалось выполнить действие. Проверьте соединение и повторите.');}
function showLogin(){$('#login').hidden=false;$('#workspace').hidden=true;$('#logout').hidden=true;}
function render(){const q=$('#search').value.trim().toLowerCase();$('#products').replaceChildren();for(const p of items.filter(p=>[p.brand,p.name,p.sku].join(' ').toLowerCase().includes(q))){const b=document.createElement('button');b.type='button';b.className='product'+(selected?.id===p.id?' active':'');const title=document.createElement('b'),meta=document.createElement('small');title.textContent=[p.brand,p.name].filter(Boolean).join(' ');meta.textContent=(p.price==null?'Цена не указана':p.price.toLocaleString('ru-RU')+' ₽')+' · '+(p.published?'В каталоге':'Черновик')+' · '+(stockLabels[p.stockStatus]||stockLabels.unknown);b.append(title,meta);b.onclick=()=>open(p);$('#products').append(b);}}
function open(p){if(dirty&&!confirm('Изменения не сохранены. Закрыть их?'))return;selected={...p};dirty=false;form.hidden=false;for(const el of form.elements){if(!el.name)continue;if(el.type==='checkbox')el.checked=!!p[el.name];else el.value=p[el.name]??'';}say($('#saveStatus'),'');$('#editorTitle').textContent=p.revision?'Редактировать товар':'Новый товар';render();}
async function load(){const data=await api('list');items=data.items;$('#workspace').hidden=false;$('#login').hidden=true;$('#logout').hidden=false;say($('#status'),'');render();}
$('#login').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{const j=await api('login',Object.fromEntries(new FormData(e.currentTarget)));csrf=j.csrf;e.currentTarget.reset();await load();}catch(e){say($('#status'),errorText(e),true);}finally{submit.disabled=false;}};
form.addEventListener('input',()=>{dirty=true;});
form.onsubmit=async e=>{e.preventDefault();const product={...selected,...Object.fromEntries(new FormData(form))};for(const key of numberFields)product[key]=form.elements[key].value===''?null:Number(form.elements[key].value);product.published=form.elements.published.checked;product.checkedAt=new Date().toLocaleDateString('ru-RU');$('#save').disabled=true;try{const j=await api('save',{product,revision:selected.revision||0});const i=items.findIndex(p=>p.id===j.product.id);if(i<0)items.push(j.product);else items[i]=j.product;selected=j.product;dirty=false;render();say($('#saveStatus'),'Сохранено. Изменения доступны на сайте.');}catch(e){say($('#saveStatus'),errorText(e),true);}finally{$('#save').disabled=false;}};
$('#search').oninput=render;$('#add').onclick=()=>open({id:'product-'+crypto.randomUUID(),revision:0,priceKind:'shop',stockStatus:'unknown',published:false});$('#cancel').onclick=()=>{if(dirty&&!confirm('Изменения не сохранены. Закрыть их?'))return;dirty=false;selected=null;form.hidden=true;render();};$('#logout').onclick=async()=>{if(dirty&&!confirm('Изменения не сохранены. Выйти?'))return;try{await api('logout',{});dirty=false;showLogin();}catch(e){say($('#status'),errorText(e),true);}};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
showLogin();
(async()=>{try{const j=await api('me');csrf=j.csrf;await load();}catch(e){if(e.message==='session_expired'){showLogin();say($('#status'),'');}else say($('#status'),errorText(e),true);}})();
})();
